/* run summary */
.rsm-head{display:flex;align-items:center;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line)}
.rsm-ic{width:32px;height:32px;flex:none;display:grid;place-items:center;background:var(--chip)}
.rsm-ht{display:flex;flex-direction:column}
.rsm-ht .t{font-weight:600;font-size:14px}
.rsm-title{padding:14px 16px 4px;font-size:15px;font-weight:600;line-height:1.4}
.rsm-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:10px 16px 14px}
.rsm-stats div{display:flex;flex-direction:column;gap:2px;padding:8px 10px;background:var(--chip)}
.rsm-stats b{font-size:16px;font-weight:600;font-variant-numeric:tabular-nums}
.rsm-stats span{font-size:11px;color:var(--muted)}
.rsm-sec{padding:10px 16px;border-top:1px solid var(--line)}
.rsm-lbl{font-family:var(--mono);font-size:10px;font-weight:700;text-transform:uppercase;color:var(--muted);margin-bottom:6px}
.rsm-it{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:4px 0;font-size:13px;transition:opacity .4s,transform .4s var(--ease)}
.rsm-it .f{font-family:var(--mono);font-size:12px;transition:color .3s}
.rsm-need .f{font-family:var(--sans);font-size:13px}
.rsm-it .d{display:flex;gap:8px;font-family:var(--mono);font-size:12px}
.rsm-it .d i{font-style:normal}
.rsm-it .a{color:var(--success)}.rsm-it .r{color:var(--danger)}
.rsm-it.pre{opacity:0;transform:translateY(4px)}
#rsm.undone .rsm-it .f{color:var(--muted);text-decoration:line-through}
#rsm.undone .rsm-it .d{opacity:.4}
.rsm-acts{display:flex;gap:8px;padding:12px 16px;border-top:1px solid var(--line)}
.rsm-acts .btn{padding:8px 12px;font-size:13px}

/* ---------- run summary ---------- */
{
  const root = $('#rsm'), undo = $('#rsm-undo'), fix = $('#rsm-fix'), nums = $$('.rsm-stats b', root), items = $$('.rsm-it', root);
  let ts = [], raf = 0;
  const fmt = (b, v) => (b.dataset.p || '') + (b.dataset.n.includes('.') ? v.toFixed(2) : Math.round(v)) + (b.dataset.u || '');
  function count(){
    cancelAnimationFrame(raf); const t0 = performance.now();
    const step = t => { const k = Math.max(0, Math.min(1, (t - t0) / 900)), e = 1 - Math.pow(1 - k, 3);
      nums.forEach(b => b.textContent = fmt(b, parseFloat(b.dataset.n) * e));
      if (k < 1) raf = requestAnimationFrame(step); };
    raf = requestAnimationFrame(step);
  }
  function play(){
    ts.forEach(clearTimeout); ts = [];
    root.classList.remove('undone'); undo.textContent = 'Undo all';
    swapText($('#rsm-t'), 'Run complete'); $('#rsm-ic').innerHTML = ic('check_circle', 'sm s-done icon-in');
    $('#rsm-need-t').textContent = 'One German label is longer than its button';
    if (!fix.isConnected) $('#rsm-need').appendChild(fix);
    items.forEach(it => it.classList.add('pre'));
    count();
    items.forEach((it, i) => ts.push(setTimeout(() => { it.classList.remove('pre'); ambient('c106', 'tick'); }, 300 + i * 140)));
  }
  undo.addEventListener('click', () => {
    const on = !root.classList.contains('undone'); root.classList.toggle('undone', on);
    undo.textContent = on ? 'Redo' : 'Undo all';
    swapText($('#rsm-t'), on ? 'Changes undone' : 'Run complete');
    $('#rsm-ic').innerHTML = ic(on ? 'undo' : 'check_circle', 'sm icon-in ' + (on ? 's-wait' : 's-done'));
    Sound.play(on ? 'pop' : 'done');
  });
  fix.addEventListener('click', () => {
    Sound.play('tab'); fix.innerHTML = '<i class="spin"></i>';
    setTimeout(() => { fix.remove(); fix.textContent = 'Review'; swapText($('#rsm-need-t'), 'Label shortened to fit, nothing left to review'); Sound.play('done'); }, 900);
  });
  $('#rsm-play').addEventListener('click', () => { Sound.play('tab'); play(); });
  whenSeen($('#c106'), play);
}
